"use strict";exports.addon=function(e){e.selector=function(e,t){var n,r,s,o,i,f=e.split(","),l=[],p=t.split(","),u=f.length,c=p.length;for(n=0;n<c;n++)if((s=p[n]).indexOf("&")>-1)for(r=0;r<u;r++)o=f[r],i=s.replace(/&/g,o),l.push(i);else for(r=0;r<u;r++)(o=f[r])?l.push(o+" "+s):l.push(s);return l.join(",")}};